/**
 * Button: the action control.
 * Purpose: every button on the site. Generated by shadcn, then re-themed to Grove. Owner: design system.
 * Props: variant ("accent" copper | "primary" forest | "secondary" outline | "ghost" | "danger" |
 *   "danger-outline"), size ("sm" 40 px | "md" 48 px | "lg" 54 px), pill, asChild (render a link or
 *   other element with the button look), plus every native button prop. Loading and icon slots: S2-T04.
 * Responsive: heights are touch sizes on every screen; dense 36 px portal buttons are a later size.
 * Accessibility: a native button; focus ring comes from the global rule. Disabled looks flat and
 *   keeps its label. One accent button per view; portals use primary (R-FE-08).
 * States: default, hover, focus, pressed, disabled.
 * Dependencies: cva, cn, radix Slot. Tests: controls.test.tsx; Design Lab "Buttons" (S2-T07).
 * UX reference: ds-components, Buttons (c-core.css .btn).
 */
import { cva, type VariantProps } from "class-variance-authority";
import { Slot } from "radix-ui";
import type { ComponentProps } from "react";
import { cn } from "@/lib/cn";

const buttonVariants = cva(
  [
    "relative inline-flex shrink-0 items-center justify-center gap-2 whitespace-nowrap select-none",
    "rounded-md border-[length:var(--bw-field)] border-transparent font-bold",
    "transition-colors duration-(--dur-fast) ease-standard active:translate-y-px",
    "disabled:cursor-not-allowed disabled:border-transparent disabled:bg-neutral-tint disabled:text-subtle disabled:active:translate-y-0",
    "[&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-5",
  ],
  {
    variants: {
      variant: {
        accent: "bg-cta text-on-cta hover:bg-cta-hover",
        primary: "bg-primary text-on-primary hover:bg-primary-hover",
        secondary: "border-primary bg-surface text-primary hover:bg-primary-tint",
        ghost: "bg-transparent px-4 text-primary hover:bg-primary-tint",
        danger: "bg-danger text-on-primary hover:brightness-90",
        "danger-outline": "border-danger bg-surface text-danger hover:bg-danger-tint",
      },
      size: {
        sm: "h-(--size-btn-sm) rounded-sm px-4 text-small",
        md: "h-(--size-btn) px-5 text-body",
        lg: "h-(--size-btn-lg) px-6 text-title",
      },
      pill: { true: "rounded-pill", false: "" },
    },
    compoundVariants: [
      {
        variant: ["secondary", "ghost"],
        className:
          "disabled:border-line-strong disabled:bg-transparent disabled:hover:bg-transparent",
      },
      { variant: "ghost", className: "disabled:border-transparent" },
    ],
    defaultVariants: { variant: "primary", size: "md", pill: false },
  },
);

type ButtonProps = Omit<ComponentProps<"button">, "ref"> &
  VariantProps<typeof buttonVariants> & { asChild?: boolean };

function Button({ className, variant, size, pill, asChild = false, ...props }: ButtonProps) {
  const Component = asChild ? Slot.Root : "button";
  return (
    <Component
      data-slot="button"
      className={cn(buttonVariants({ variant, size, pill }), className)}
      {...props}
    />
  );
}

export { Button, buttonVariants };
